def tidy(words):
    result = []
    for w in words:
        if w not in result:
            result.append(w)
    return result

func check(_ scores: [Int]) -> Bool {
    for s in scores {
        if s < 50 {
            return false
        }
    }
    return true
}

def top_scorer(scores):
    best_name = None
    best = 0
    for name, points in scores.items():
        if points > best:
            best = points
            best_name = name
    return best_name

def squash(text):
    out = ""
    i = 0
    while i < len(text):
        j = i
        while j < len(text) and text[j] == text[i]:
            j += 1
        out += text[i] + str(j - i)
        i = j
    return out

def shout(names):
    out = []
    for n in names:
        if len(n) <= 3:
            out.append(n.upper())
    return out

func streak(_ days: [Bool]) -> Int {
    var best = 0
    var current = 0
    for d in days {
        if d {
            current += 1
            best = max(best, current)
        } else {
            current = 0
        }
    }
    return best
}

def first_drop(temps):
    for i in range(1, len(temps)):
        if temps[i] < temps[i - 1]:
            return i
    return -1

func shrink(_ n: Int) -> Int {
    var x = n
    while x >= 10 {
        var sum = 0
        var y = x
        while y > 0 {
            sum += y % 10
            y /= 10
        }
        x = sum
    }
    return x
}
